*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/utils.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/controlResize.js"); // 화면 리사이징

scwin.vScrenID = "ULDFIS00200_18.gfm";
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsStrtDt = ""; // 조회조건 결산일자 FROM
scwin.vAcntclsEndDt = "";
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
}; // 조회조건 결산일자 TO

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    // 결산일자 조회
    // 결산일자 From To 변경
    //frame.Provider("../frame_head").fn_SrchAcntclsDt();

    scwin.fn_Search();
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_MngAdmCompst.removeAll();
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    //필수항목 체크.

	//----W-Craft WebSquare 변환 확인: fn_GetKisCd----//
    scwin.vKisCd = $c.frame.path("../frame_head").fn_GetKisCd();

	//----W-Craft WebSquare 변환 확인: fn_GetAcntclsStrtDt----//
    scwin.vAcntclsStrtDt = $c.frame.path("../frame_head").fn_GetAcntclsStrtDt();

	//----W-Craft WebSquare 변환 확인: fn_GetAcntclsEndDt----//
    scwin.vAcntclsEndDt = $c.frame.path("../frame_head").fn_GetAcntclsEndDt();
    if (scwin.vKisCd == "" || scwin.vAcntclsStrtDt == "" || scwin.vAcntclsEndDt == "") {
        return false;
    }
    return true;
};


/**
 * 경영진구성 조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_MngAdmCompst);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.mngAdmCompst" + "&outputMessageId=FIS_MNG_ADM_COMPST" + "&param01=" + scwin.vKisCd + "&param02=" + scwin.vAcntclsStrtDt + "&param03=" + scwin.vAcntclsEndDt;
    dts_MngAdmCompst.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_MngAdmCompst.Reset();
};


/**
 * 경영진상세조회 팝업
 */
scwin.fn_MngAdmDtlSrchOpen = async function() {
    fn_GetPar = fn_GetParKey;
    await $c.frame.CreateDialogFrame("MNG_ADM_DTL", "./ULDFIS00200_P1.gfm", "인물 검색", 100, 100, 590 + 20, 377 + 45, "window");
};


/**
 * 팝업으로 값을 넘김.
 */
scwin.fn_GetParKey = function(arrPar) {
    var nRow = dts_MngAdmCompst.getRowPosition();
    arrPar[0] = dts_MngAdmCompst.getCellData(nRow, "PERSON_CD");
    arrPar[1] = dts_MngAdmCompst.getCellData(nRow, "KIS_CD");
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/**
 *  엑셀파일다운로드
 */
scwin.fn_excel_download = function() {
    if (dts_MngAdmCompst.getTotalRow() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_MngAdmCompst, "경영진구성", "", "1");
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.dts_MngAdmCompst_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_MngAdmCompst);
    $c.stf.alert_error(dts_MngAdmCompst);
};
scwin.dts_MngAdmCompst_OnLoadCompleted = function(rowcount) {
    if (dts_MngAdmCompst.errorMsg) {
        alert(dts_MngAdmCompst.errorMsg);
    }
    $c.cm.CloseWin(rowcount, grd_MngAdmCompst);
};
scwin.grd_MngAdmCompst_OnDblClick = function(row, colid) {
    if (colid == "NM") {
        // 경영자상세조회 팝업 오픈

        // fn_MngAdmDtlSrchOpen();

    }
};
